const body = $input.first().json.body || {};
const opportunityId = parseInt(body.opportunity_id, 10);
if (!Number.isInteger(opportunityId)) throw new Error('"opportunity_id" is required and must be an integer.');
const dealStage = (body.deal_stage || '').toString().trim();
if (!dealStage) throw new Error('"deal_stage" is required.');

return [{ json: { opportunityId, dealStage } }];

const parsed = $('Parse & Validate Payload').first().json;
const row = $input.first().json;
if (!row || !row.id) throw new Error('Deal not found.');

return [{ json: {
  opportunityId: row.id,
  contactId: row.contact_id,
  pipelineId: row.pipeline_id,
  dealStage: parsed.dealStage,
} }];

